def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_threat = 0
    urgent_opp = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 300:
                rich_threat += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if tightness < 0:
        tightness = 0.0
    if tightness > 1:
        tightness = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 0.55
    elif hp <= 4:
        danger += 0.35
    elif hp <= 6:
        danger += 0.18

    if no_water_days >= 2:
        danger += 0.35
    elif no_water_days >= 1:
        danger += 0.18

    pressure = 0.0
    if highest_prev >= 120:
        pressure += 0.28
    elif highest_prev >= 90:
        pressure += 0.18
    elif highest_prev >= 60:
        pressure += 0.08

    pressure += min(0.18, rich_threat * 0.06)
    pressure += min(0.12, urgent_opp * 0.04)

    base = 16.0 + 18.0 * tightness + 42.0 * danger + 24.0 * pressure

    if supply <= 17:
        base += 10.0
    elif supply >= 23:
        base -= 6.0

    if hp >= 7 and no_water_days == 0 and highest_prev >= 100:
        base = min(base, 34.0 + 8.0 * tightness)

    if hp <= 3 or no_water_days >= 2:
        emergency = max(0.88 * DAILY_SALARY, highest_prev + 3.0)
        base = max(base, emergency)

    if highest_prev > 0 and hp > 4 and no_water_days == 0:
        shadow = highest_prev * (0.58 + 0.12 * tightness)
        if shadow < base:
            base = max(base - 4.0, shadow)

    if avg_prev > 0 and avg_prev < 50 and supply >= 21 and hp >= 6:
        base = min(base, avg_prev + 6.0)

    reserve_floor = DAILY_SALARY * 1.2 if hp > 3 else DAILY_SALARY * 0.4
    spendable = budget - reserve_floor
    if spendable < 8.0:
        spend_cap = budget
    else:
        spend_cap = max(8.0, spendable)

    bid = min(base, spend_cap, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    my_hp = my_status.get('hp', 0)
    my_budget = my_status.get('budget', 0)
    my_no_water_days = my_status.get('no_water_days', 0)

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    # Baseline: if we're in danger, spend to secure water.
    danger = (my_hp <= 2) or (my_no_water_days >= 2)

    # React to yesterday pressure: look at bids of alive opponents from their previous_trace.
    prev_bids = []
    for _, opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])

    # If we can estimate market pressure, bid around it.
    if prev_bids:
        highest_prev = max(prev_bids)
        # If someone previously bid extremely high, avoid going to the ceiling.
        # Use a cap factor based on how close supply is to the minimum.
        supply_frac = 0.0
        if MAX_SUPPLY > MIN_SUPPLY:
            supply_frac = (float(supply) - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
        if supply_frac < 0.0:
            supply_frac = 0.0
        if supply_frac > 1.0:
            supply_frac = 1.0

        # When supply is scarce, we must be more aggressive.
        scarcity_multiplier = 1.15 if supply_frac < 0.35 else (1.0 if supply_frac < 0.7 else 0.85)

        # Target bid: slightly below the highest previous bid unless we're in danger.
        if danger:
            target = min(my_budget, highest_prev * (0.92 * scarcity_multiplier) + 2.0)
        else:
            target = min(my_budget, max(DAILY_SALARY * 0.45, highest_prev * (0.72 * scarcity_multiplier)))
    else:
        # No signal: use supply-based heuristic.
        supply_frac = 0.0
        if MAX_SUPPLY > MIN_SUPPLY:
            supply_frac = (float(supply) - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
        if supply_frac < 0.0:
            supply_frac = 0.0
        if supply_frac > 1.0:
            supply_frac = 1.0
        if danger:
            target = DAILY_SALARY * 0.9
        else:
            target = DAILY_SALARY * (0.65 if supply_frac < 0.5 else 0.5)
        target = min(my_budget, target)

    # Ensure we never bid negative and keep within budget.
    if target < 0:
        target = 0.0
    if my_budget <= 0:
        return 0.0
    if target > my_budget:
        target = my_budget

    # If supply is very low, add a small bump to avoid tie-losing.
    if float(supply) <= float(MIN_SUPPLY) + 0.5:
        target = min(my_budget, target + DAILY_SALARY * 0.08)

    # Final small sanity cap: don't exceed ~1.05*DAILY_SALARY unless danger.
    if not danger:
        cap = DAILY_SALARY * 1.05
        if target > cap:
            target = cap

    return float(target)

